-- PURPOSE: Check sourced positive-index boundaries and safe profile exclusions.
-- CHANGE THIS MODULE WHEN: The documented compact deviation profile changes.
-- DO NOT PUT HERE: Index expectations generated by the lookup under test.

local test = require("tests.harness")
local fixtures = require("tests.fixtures")
local rules = require("src.blackjack.rules")
local hand = require("src.blackjack.hand")
local actions = require("src.blackjack.player_actions")
local basic = require("src.training.basic_strategy")
local deviations = require("src.training.deviations")
local copy = require("src.plain_copy")
local deviation_tests = {}

local examples = {
    { ranks = { "10", "5" }, upcard = "10", index = 4, id = "15_v_10" },
    { ranks = { "10", "2" }, upcard = "3", index = 2, id = "12_v_3" },
    { ranks = { "10", "2" }, upcard = "2", index = 3, id = "12_v_2" },
    { ranks = { "10", "6" }, upcard = "9", index = 5, id = "16_v_9" },
}

local function decision(example)
    local card_ids = fixtures.ids({ example.ranks[1], example.ranks[2], example.upcard, "7" })
    return {
        rules = rules.defaults(),
        phase = "player_turn",
        bankroll_units = 1000,
        round = {
            active_hand = 1,
            hands = { hand.new({ card_ids[1], card_ids[2] }, 100) },
            dealer = { cards = { card_ids[3], card_ids[4] } },
        },
    }
end

local function public_counts(true_count)
    -- 156 exposed cards in a six-deck shoe leave exactly three estimated decks.
    return { running = true_count * 3, true_count = true_count, decks = 3, exposed = 156 }
end

function deviation_tests.run()
    for _, example in ipairs(examples) do
        test.test(example.id .. " keeps basic Hit below its published index", function()
            local game = decision(example)
            local advice = assert(basic.recommend(game))
            test.equal(advice.action, "hit")
            local adjusted, reason =
                deviations.recommend(game, public_counts(example.index - 1), advice)
            test.equal(adjusted, nil)
            assert(reason:find("not been reached", 1, true))
            test.equal(advice.action, "hit", "Basic strategy remains distinct")
        end)
        test.test(example.id .. " changes Hit to Stand exactly at its published index", function()
            local game = decision(example)
            local advice = assert(basic.recommend(game))
            local counts = public_counts(example.index)
            local before_game, before_counts, before_advice = copy(game), copy(counts), copy(advice)
            local adjusted = assert(deviations.recommend(game, counts, advice))
            test.equal(adjusted.action, "stand")
            test.equal(adjusted.basic_action, "hit")
            test.equal(adjusted.index, example.index)
            test.equal(adjusted.id, example.id)
            test.equal(adjusted.profile, "hi_lo_i18_s17_6d_positive_stands_v1")
            assert(actions.legal(game)[adjusted.action])
            test.same(game, before_game)
            test.same(counts, before_counts)
            test.same(advice, before_advice)
        end)
        test.test(example.id .. " keeps Stand above its published index", function()
            local game = decision(example)
            test.equal(
                assert(
                    deviations.recommend(
                        game,
                        public_counts(example.index + 1),
                        basic.recommend(game)
                    )
                ).action,
                "stand"
            )
        end)
    end

    test.test(
        "only the three penetration variants of the exact six-deck S17 profile are enabled",
        function()
            local supported = 0
            for _, decks in ipairs({ 6, 8 }) do
                for _, h17 in ipairs({ false, true }) do
                    for _, double_rule in ipairs({ "any_two", "9_to_11", "10_to_11" }) do
                        for _, das in ipairs({ true, false }) do
                            for _, penetration in ipairs({ 50, 67, 75 }) do
                                local preset = rules.defaults()
                                preset.deck_count = decks
                                preset.dealer_hits_soft_17 = h17
                                preset.double_rule = double_rule
                                preset.double_after_split = das
                                preset.penetration_percent = penetration
                                local enabled, reason = deviations.supported(preset)
                                local expected = decks == 6
                                    and not h17
                                    and double_rule == "any_two"
                                    and das
                                test.equal(enabled, expected)
                                if enabled then
                                    supported = supported + 1
                                else
                                    assert(type(reason) == "string")
                                end
                            end
                        end
                    end
                end
            end
            test.equal(supported, 3)
        end
    )
    test.test(
        "unsupported future surrender insurance no-peek and payout rules omit advice",
        function()
            local changes = {
                { "surrender", true },
                { "insurance", true },
                { "dealer_peek", false },
                { "blackjack_profit_numerator", 6 },
            }
            for _, change in ipairs(changes) do
                local game = decision(examples[1])
                game.rules[change[1]] = change[2]
                local adjusted, reason =
                    deviations.recommend(game, public_counts(6), { action = "hit" })
                test.equal(adjusted, nil)
                assert(type(reason) == "string")
            end
        end
    )
    test.test("pairs split hands and three-card totals receive no unsourced deviation", function()
        local game = decision(examples[4])
        game.round.hands[1].cards = fixtures.ids({ "8", "8" })
        assert(not deviations.recommend(game, public_counts(6), { action = "hit" }))
        game = decision(examples[1])
        game.round.hands[1].from_split = true
        assert(not deviations.recommend(game, public_counts(6), basic.recommend(game)))
        game.round.hands[1].from_split = false
        game.round.hands[1].cards = fixtures.ids({ "10", "3", "2" })
        assert(not deviations.recommend(game, public_counts(6), basic.recommend(game)))
    end)
    test.test("soft totals and unrelated hard totals keep their basic policy", function()
        local game = decision(examples[1])
        game.round.hands[1].cards = fixtures.ids({ "A", "4" })
        assert(not deviations.recommend(game, public_counts(6), basic.recommend(game)))
        game.round.hands[1].cards = fixtures.ids({ "10", "4" })
        assert(not deviations.recommend(game, public_counts(6), basic.recommend(game)))
    end)
    test.test("a result has no deviation even if its count crosses an index", function()
        local game = decision(examples[1])
        game.phase = "round_result"
        assert(not deviations.recommend(game, public_counts(6), { action = "hit" }))
    end)
    test.test("hidden dealer card and undrawn shoe never affect deviation lookup", function()
        local game = decision(examples[1])
        local counts = public_counts(4)
        local expected = assert(deviations.recommend(game, counts, basic.recommend(game)))
        game.round.dealer.cards[2] = fixtures.ids({ "A" })[1]
        game.shoe = { order = { 999999 }, next_index = 0 }
        test.same(assert(deviations.recommend(game, counts, basic.recommend(game))), expected)
    end)
    test.test("wrong deck estimate and stale true count fail safely", function()
        local game = decision(examples[1])
        local counts = public_counts(4)
        counts.decks = 2.5
        assert(not deviations.recommend(game, counts, basic.recommend(game)))
        counts = public_counts(4)
        counts.true_count = 5
        assert(not deviations.recommend(game, counts, basic.recommend(game)))
        counts = public_counts(4)
        counts.exposed = 313
        assert(not deviations.recommend(game, counts, basic.recommend(game)))
        assert(not deviations.recommend(game, nil, basic.recommend(game)))
    end)
    test.test(
        "positive fractional true count triggers only after the locked integer reaches the index",
        function()
            local game = decision(examples[1])
            -- RC 11 / three decks = 3.666, truncated to +3, still below +4.
            local below = { running = 11, decks = 3, exposed = 156, true_count = 3 }
            assert(not deviations.recommend(game, below, basic.recommend(game)))
            local at = { running = 12, decks = 3, exposed = 156, true_count = 4 }
            test.equal(
                assert(deviations.recommend(game, at, basic.recommend(game))).action,
                "stand"
            )
        end
    )
    test.test("negative counts do not borrow omitted zero or negative indices", function()
        local game = decision(examples[1])
        assert(not deviations.recommend(game, public_counts(-5), basic.recommend(game)))
        game.round.hands[1].cards = fixtures.ids({ "10", "6" })
        assert(not deviations.recommend(game, public_counts(0), basic.recommend(game)))
    end)
end

return deviation_tests
